   var other=new ClxnDocument();other.LoadDefault();File.AppendAllText(other.SavePath," ");other.Commit();Assert(other.LastError!=null,"Stale window refuses to overwrite external changes"); var camera=new CodeWalker.World.Camera(10,.005f,1){FieldOfView=1,FollowEntity=new CodeWalker.World.Entity(),TargetRotation=new Vector3(.3f,-.65f,0),CurrentRotation=Vector3.Zero,TargetDistance=12,VOffset=2,Smoothness=10};var target=new Vector3(-300.25f,177.5f,114.75f);ClxnCameraNavigation.Restore(camera,target);Assert(Vector3.Distance(camera.Position,target)<.001f,"Teleport restores actual camera XYZ, not orbit target");for(int frame=0;frame<120;frame++)camera.Update(1f/60);Assert(Vector3.Distance(camera.Position,target)<.001f,"Camera remains at restored XYZ after smoothing frames"); var scene=new ClxnDocument{ViewPosition=new Vector3(10,20,30),ViewRotation=new Vector3(.2f,.4f,0),MapProjectPath="C:/Map/custom.cwproj"};scene.Pins.Add(new ClxnPin{Model="s_m_m_paramedic_01",Heading=125,Position=new Vector3(4,5,6)});scene.Strokes.Add(new ClxnStroke{Colour=unchecked((int)0xff5fe5c1),Width=7,Points={new Vector3(1,2,3),new Vector3(2,3,4)}});var restored=new ClxnDocument();restored.Deserialize(scene.Serialize());Assert(restored.Pins[0].Model==scene.Pins[0].Model&&restored.Pins[0].Heading==125,"Scene roundtrip restores actor model and heading");Assert(restored.ViewPosition==scene.ViewPosition&&restored.ViewRotation==scene.ViewRotation&&restored.MapProjectPath==scene.MapProjectPath,"Scene roundtrip restores camera and map reference");Assert(restored.Strokes[0].Colour==scene.Strokes[0].Colour&&restored.Strokes[0].Width==7,"Scene roundtrip preserves exact brush colour and width"); float groundDistance;Assert(ClxnGroundMath.Triangle(new Ray(new Vector3(.2f,.2f,10),-Vector3.UnitZ),new Vector3(0,0,3),new Vector3(1,0,3),new Vector3(0,1,3),out groundDistance)&&Math.Abs(groundDistance-7)<.0001f,"Visible roof triangle resolves surface above lower collision floor");Assert(!ClxnGroundMath.Triangle(new Ray(new Vector3(2,2,10),-Vector3.UnitZ),new Vector3(0,0,3),new Vector3(1,0,3),new Vector3(0,1,3),out groundDistance),"Ground picking rejects points outside triangle");Assert(Math.Abs(ClxnGroundMath.RootHeight(35,-.8f)-35.825f)<.0001f,"Actor lowest point rests above chosen surface");Assert(Math.Abs(ClxnGroundMath.RootHeight(35,.2f)-35.025f)<.0001f,"Actor with nonnegative model bound is not sunk into floor"); var flight=new ClxnDocument();flight.CameraKeys.Add(new ClxnCameraKey{Name="Старт",Position=new Vector3(0,0,10),Rotation=new Vector3(3.124f,0,0),Seconds=2,Fov=1});flight.CameraKeys.Add(new ClxnCameraKey{Name="Финиш",Position=new Vector3(10,0,20),Rotation=new Vector3(-3.124f,.2f,0),Seconds=80,Fov=.8f});var flightCopy=new ClxnDocument();flightCopy.Deserialize(flight.Serialize());Assert(flightCopy.CameraKeys.Count==2&&flightCopy.CameraKeys[1].Name=="Финиш"&&flightCopy.SmoothFlight,"Flight roundtrip restores ordered keys and smoothing");Assert(Math.Abs(ClxnFlightMath.Duration(flight.CameraKeys)-2)<.0001f,"Flight duration excludes unused last key interval");Vector3 flightPos,flightRot;float flightFov;ClxnFlightMath.Evaluate(flight.CameraKeys,1,true,out flightPos,out flightRot,out flightFov);Assert(Vector3.Distance(flightPos,new Vector3(5,0,15))<.001f&&Math.Abs(flightFov-.9f)<.001f,"Flight midpoint interpolates position and FOV");Assert(Math.Abs(flightRot.X-(float)Math.PI)<.01f,"Flight yaw takes shortest path across 180 degrees");ClxnFlightMath.Evaluate(flight.CameraKeys,500,true,out flightPos,out flightRot,out flightFov);Assert(flightPos==flight.CameraKeys[1].Position,"Playback clamps at final camera key");ClxnFlightMath.Evaluate(flight.CameraKeys,-2,true,out flightPos,out flightRot,out flightFov);Assert(flightPos==flight.CameraKeys[0].Position,"Playback clamps negative time at start");var flightBefore=flightCopy.Serialize();try{flightCopy.Deserialize(flightBefore.Replace("seconds=\"2\"","seconds=\"NaN\""));throw new Exception("Expected invalid flight duration");}catch(FormatException){}Assert(flightCopy.Serialize()==flightBefore,"Invalid flight import preserves existing scene");flight.Checkpoint();flight.CameraKeys.RemoveAt(0);flight.Commit();flight.Undo();Assert(flight.CameraKeys.Count==2,"Undo restores removed camera key");var oldScene=new ClxnDocument();oldScene.Deserialize(before);Assert(oldScene.CameraKeys.Count==0,"Legacy scene without flight keys remains supported");var journal=new ClxnJournal();journal.Add("one");journal.Add("one");Assert(journal.Snapshot().Length==1,"Journal suppresses consecutive duplicate messages");for(int i=0;i<250;i++)journal.Add("event "+i);Assert(journal.Snapshot().Length==200&&journal.Snapshot()[199].EndsWith("event 249"),"Journal retains only 200 newest events");journal.Clear();Assert(journal.Snapshot().Length==0,"Journal can be cleared"); Assert(ClxnVideoPlan.FrameCount(8,30)==240&&ClxnVideoPlan.FrameCount(.3f,30)==9,"MP4 frame count follows exact duration and selected FPS");Assert(Math.Abs(ClxnVideoPlan.TimeForFrame(60,30)-2)<.0001f,"MP4 camera time depends on frame index, not render speed");try{ClxnVideoPlan.FrameCount(float.NaN,30);throw new Exception("Expected invalid duration");}catch(ArgumentOutOfRangeException){}try{ClxnVideoPlan.FrameCount(8,0);throw new Exception("Expected invalid FPS");}catch(ArgumentOutOfRangeException){}Assert(true,"MP4 plan rejects nonfinite duration and invalid FPS");
   var all=new ClxnDocument{SavePath=Path.Combine(ClxnHomeForm.DataFolder,"clear-scene.clxn"),ViewPosition=new Vector3(1,2,3),MapProjectPath="test.cwproj"};all.Pins.Add(new ClxnPin{Model="vehicle:oracle",Heading=75,Position=new Vector3(2,3,4)});all.Pins.Add(new ClxnPin{Model="clxn:white",Outfit={new ClxnClothingPart{Component=11,Drawable=2,Texture=1,DrawablePath="D:/Одежда/top.ydd",TexturePath="D:/Одежда/top.ytd"}}});all.Strokes.Add(new ClxnStroke{Points={Vector3.One,Vector3.Zero}});all.CameraKeys.Add(new ClxnCameraKey{Position=Vector3.One});var allXml=all.Serialize();var allCopy=new ClxnDocument();allCopy.Deserialize(allXml);Assert(allCopy.Pins[0].IsVehicle&&!allCopy.Pins[0].IsPed&&allCopy.Pins[1].IsPed,"Vehicle and pedestrian types remain distinct after save/load");Assert(allCopy.Pins[1].Outfit[0].DrawablePath=="D:/Одежда/top.ydd"&&allCopy.Pins[1].Outfit[0].Texture==1,"Clothing variants and external resources survive scene roundtrip");all.ClearAll();Assert(all.Pins.Count==0&&all.Strokes.Count==0&&all.CameraKeys.Count==0&&!all.ViewPosition.HasValue,"Clear all removes models, clothing, markers, drawing and camera keys");all.Undo();Assert(all.Serialize()==allXml,"Single undo restores complete scene after clear all");all.Undo(true);Assert(all.Pins.Count==0&&all.Strokes.Count==0&&all.CameraKeys.Count==0,"Redo repeats complete scene clear");var invalidOutfit=allCopy.Serialize();try{allCopy.Deserialize(invalidOutfit.Replace("component=\"11\"","component=\"12\""));throw new Exception("Expected invalid outfit");}catch(FormatException){}Assert(allCopy.Serialize()==invalidOutfit,"Malformed clothing import preserves current scene");
   var atmosphere=new ClxnDocument{SkyWeather="SMOG",SkyHour=23.933f,SkyCloud="contrails",SkyClouds=false,SkyVisible=true,SkyGray=true,SavePath=Path.Combine(ClxnHomeForm.DataFolder,"sky.clxn")};var skyRound=new ClxnDocument();skyRound.Deserialize(atmosphere.Serialize());Assert(skyRound.SkyWeather=="SMOG"&&Math.Abs(skyRound.SkyHour-23.933f)<.001f&&!skyRound.SkyClouds&&skyRound.SkyVisible&&skyRound.SkyGray,"Sky weather, time and clouds survive scene roundtrip");var validSky=skyRound.Serialize();try{skyRound.Deserialize(validSky.Replace("hour=\"23.933\"","hour=\"NaN\""));throw new Exception("Expected invalid sky time");}catch(FormatException){}Assert(skyRound.Serialize()==validSky,"Invalid atmosphere import preserves current scene");atmosphere.Checkpoint();atmosphere.SkyWeather="CLEAR";atmosphere.SkyHour=12;atmosphere.Commit();atmosphere.Undo();Assert(atmosphere.SkyWeather=="SMOG"&&Math.Abs(atmosphere.SkyHour-23.933f)<.001f,"Undo restores previous sky and time");atmosphere.ClearAll();Assert(atmosphere.SkyWeather=="SMOG","Scene clear preserves base map atmosphere");
   var posed=new ClxnDocument{SavePath=Path.Combine(ClxnHomeForm.DataFolder,"poses.clxn")};posed.Pins.Add(new ClxnPin{Model="clxn:white",Pose="sit"});posed.Pins.Add(new ClxnPin{Model="clxn:white",Pose="dance"});var posedCopy=new ClxnDocument();posedCopy.Deserialize(posed.Serialize());Assert(posedCopy.Pins[0].Pose=="sit"&&posedCopy.Pins[1].Pose=="dance","Scene roundtrip preserves per-character sitting and dancing");var poseBefore=posedCopy.Serialize();try{posedCopy.Deserialize(poseBefore.Replace("pose=\"sit\"","pose=\"unknown\""));throw new Exception("Expected invalid pose");}catch(FormatException){}Assert(posedCopy.Serialize()==poseBefore,"Invalid pose import preserves existing scene");posed.Checkpoint();posed.Pins[0].Pose="stand";posed.Commit();posed.Undo();Assert(posed.Pins[0].Pose=="sit","Undo restores character pose");
