   Assert(ClxnShortcuts.ToolForKey(49)=="move"&&ClxnShortcuts.ToolForKey(50)=="draw"&&ClxnShortcuts.ToolForKey(51)=="pin"&&ClxnShortcuts.ToolForKey(52)=="actor","Number keys 1-4 select requested editor tools");Assert(ClxnShortcuts.ToolForKey(97)=="move"&&ClxnShortcuts.ToolForKey(100)=="actor","Numpad tool keys match number row");Assert(ClxnShortcuts.ToolForKey(0x10000|49)==null&&ClxnShortcuts.ToolForKey(0x20000|50)==null&&ClxnShortcuts.ToolForKey(53)==null,"Modified digits and unrelated keys keep normal behavior");var roltik=new ClxnDocument();roltik.Pins.Add(new ClxnPin{Name="Roltik",Model="clxn:roltik",Pose="sit",Outfit={new ClxnClothingPart{Component=11,Drawable=1}}});var roltikCopy=new ClxnDocument();roltikCopy.Deserialize(roltik.Serialize());Assert(roltikCopy.Pins[0].IsRoltik&&roltikCopy.Pins[0].Name=="Roltik"&&roltikCopy.Pins[0].Outfit.Count==1,"Roltik scene preserves profile, name, pose and clothing");var legacyRoltik=new ClxnDocument();legacyRoltik.Deserialize(roltik.Serialize().Replace("clxn:roltik","clxn:white").Replace("name=\"Roltik\"","name=\"666 · белый / blackwork\""));Assert(legacyRoltik.Pins[0].IsRoltik&&legacyRoltik.Pins[0].Name=="Roltik","Legacy white character resolves to Roltik without losing outfit");
