   if(args.Length>=2){var encoder=new ClxnMp4Encoder(args[0],args[1],64,64,64,64,24);for(int frame=0;frame<24;frame++){byte[] buffer;var deadline=DateTime.UtcNow.AddSeconds(10);while(!encoder.TryRent(out buffer)){if(DateTime.UtcNow>deadline||encoder.Finished)throw new Exception("Encoder buffer timeout: "+encoder.Error);System.Threading.Thread.Sleep(2);}for(int i=0;i<buffer.Length;i+=4){buffer[i]=(byte)(frame*10);buffer[i+1]=100;buffer[i+2]=200;buffer[i+3]=255;}while(!encoder.TryQueue(buffer)){if(encoder.Finished)throw new Exception(encoder.Error);System.Threading.Thread.Sleep(2);}}encoder.Complete();encoder.Completion.Wait(30000);Assert(encoder.Finished&&encoder.Success&&encoder.WrittenFrames==24&&File.Exists(args[1]),"FFmpeg integration encodes all 24 frames into MP4");var cancelPath=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[1])),"cancel-preserves.mp4");File.WriteAllText(cancelPath,"original");var cancel=new ClxnMp4Encoder(args[0],cancelPath,64,64,64,64,30);cancel.Cancel();cancel.Completion.Wait(10000);Assert(cancel.Finished&&!cancel.Success&&File.ReadAllText(cancelPath)=="original","Cancelled export preserves previous destination file");File.Delete(cancelPath);}
